#![allow(dead_code)]
#[path="../../rust/processing.rs"]mod processing;
use std::{fs,path::Path};
fn read(path:&Path)->Vec<f64>{fs::read(path).unwrap().chunks_exact(8).map(|b|f64::from_le_bytes(b.try_into().unwrap())).collect()}
fn main(){let arg=std::env::args().nth(1).unwrap();let root=Path::new(&arg);let mut compared=0;let mut failures=0;let mut cases=0;
for(line_no,line)in fs::read_to_string(root.join("cases.tsv")).unwrap().lines().enumerate(){let c:Vec<_>=line.split('\t').collect();let src=read(&root.join(c[1]));let expected=read(&root.join(c[2]));let n=|i:usize|c[i].parse::<f64>().unwrap();
let actual=match c[0]{"I"=>{let a=processing::integrate(&src,n(3),n(4),c[5]=="true",c[6].parse().unwrap()).unwrap();let v=a.value();let mut out=a.curve;out.extend([a.bias,a.slope,v,v*0.123456]);out},"P"=>processing::phase(&src,&read(&root.join(c[3])),n(4),n(5),c[6].parse().unwrap()),"B"=>{let start=c[3].parse().unwrap();let count=c[4].parse().unwrap();processing::polynomial(&src,[n(5),n(6),n(7),n(8),n(9)],start,count).unwrap()[start..start+count].to_vec()},"C"=>{let corrected=processing::polynomial(&src,[n(3),n(4),n(5),n(6),n(7)],0,src.len()).unwrap();let a=processing::integrate(&corrected,12.3,-1.234,true,c[8].parse().unwrap()).unwrap();let v=a.value();let mut out=a.curve;out.extend([a.bias,a.slope,v,v*0.123456]);out},"N"=>vec![processing::normalization(&src,c[3].parse().unwrap(),n(4),n(5),c[6].parse().unwrap())],_=>panic!()};
cases+=1;assert_eq!(actual.len(),expected.len(),"case {line_no}");let mut bad=false;for(i,(a,b))in actual.iter().zip(&expected).enumerate(){compared+=1;if a.to_bits()!=b.to_bits(){if !bad{eprintln!("FAIL {} case {} sample {} {:016x} != {:016x}",c[0],line_no,i,a.to_bits(),b.to_bits());bad=true;}failures+=1;}}
 }
if let Some(live)=std::env::args().nth(2){let live=Path::new(&live);let real=read(&live.join("real.f64"));let imag=read(&live.join("imag.f64"));
 for(line_no,line)in fs::read_to_string(live.join("phase.tsv")).unwrap().lines().enumerate(){let c:Vec<_>=line.split('\t').collect();let start=c[3].parse().unwrap();let actual=processing::phase_range(&real,&imag,c[1].parse().unwrap(),c[2].parse().unwrap(),real.len(),start,real.len()-start);let expected=read(&live.join(c[0]));cases+=1;for(i,(a,b))in actual.iter().zip(&expected).enumerate(){compared+=1;if a.to_bits()!=b.to_bits(){if i==0{eprintln!("FAIL captured phase {line_no}");}failures+=1;}}}
 for line in fs::read_to_string(live.join("integral.tsv")).unwrap().lines(){let c:Vec<_>=line.split('\t').collect();let actual=processing::integrate(&real,c[3].parse().unwrap(),c[4].parse().unwrap(),c[1]=="true",c[2].parse().unwrap()).unwrap();let expected=read(&live.join(c[0]));cases+=1;assert_eq!(actual.curve.len(),expected.len());for(a,b)in actual.curve.iter().zip(&expected){compared+=1;if a.to_bits()!=b.to_bits(){failures+=1;}}}
}
println!("NATIVE_ORACLE cases={cases} raw_bit_comparisons={compared} mismatches={failures}");if failures>0{std::process::exit(1)} }
